import test from 'node:test';import assert from './assert.mjs';import {JSDOM} from 'jsdom';import {act,createElement as h,createRef,StrictMode} from 'react';import {renderToString} from 'react-dom/server';import {userEvent} from '@testing-library/user-event';import {OTPVerificationBlock} from '@dmf-ui/react';import {OTPProof,renderOTP} from '../.test-dist/server.mjs';
test('packed OTP preserves native text semantics and isolates resend payloads',()=>{const dom=new JSDOM(renderToString(h(OTPVerificationBlock,{id:'otp',action:'/verify',challengeState:'ready',resendAction:'/resend',codeName:'verificationCode',codeLength:6,fieldErrors:{code:'Review the code'},fields:h('input',{type:'hidden',name:'verifyContext',defaultValue:'verification'}),resendFields:h('input',{type:'hidden',name:'resendContext',defaultValue:'resend'})})));try{const d=dom.window.document,f=d.querySelector('#otp'),r=d.querySelector('#otp-resend'),input=f.elements.namedItem('verificationCode');assert(f.parentElement===r.parentElement);assert(!f.contains(r));assert.equal(input.type,'text');assert.equal(input.inputMode,'numeric');assert.equal(input.autocomplete,'one-time-code');assert.equal(input.pattern,'[0-9]{6}');assert.equal(input.maxLength,6);assert.equal(input.dir,'ltr');assert(!input.hasAttribute('value'));input.value='001234';assert.equal(new dom.window.FormData(f).get('verificationCode'),'001234');assert(!new dom.window.FormData(r).has('verificationCode'));assert(!new dom.window.FormData(r).has('verifyContext'));assert.equal(new dom.window.FormData(r).get('resendContext'),'resend');assert.equal(input.getAttribute('aria-describedby'),'otp-code-help otp-code-error');f.reset();assert.equal(input.value,'');}finally{dom.window.close();}
 for(const state of ['unverified','expired','locked']){const d=new JSDOM(renderToString(h(OTPVerificationBlock,{id:'inactive',action:'/verify',challengeState:state,fields:h('input',{name:'extra'})})));try{assert.equal(d.window.document.querySelector('input'),null);}finally{d.window.close();}}for(const codeLength of [0,13,1.5])assert.throws(()=>renderToString(h(OTPVerificationBlock,{id:'bad',action:'/verify',codeLength})),/codeLength/);
});
test('packed OTP hydration preserves status and host controls verify/resend, expiry, error and focus',async()=>{const dom=new JSDOM(`<div id="root">${renderOTP()}</div>`,{url:'https://consumer.test/otp.html'}),saved=new Map(),warnings=[];for(const key of ['window','document','HTMLElement','HTMLInputElement','navigator','FormData','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}let root;const old=console.error;console.error=(...args)=>warnings.push(args.join(' '));try{const {hydrateRoot}=await import('react-dom/client'),original=document.querySelector('#packed-otp-status');await act(async()=>{root=hydrateRoot(document.querySelector('#root'),h(StrictMode,{},h(OTPProof)),{identifierPrefix:'otp-',onRecoverableError:e=>warnings.push(String(e))});});assert(original===document.querySelector('#packed-otp-status'));assert.equal(document.querySelector('#packed-otp input'),null);const user=userEvent.setup({document}),press=async text=>act(async()=>user.click([...document.querySelectorAll('button')].find(b=>b.textContent===text)));await press('Show ready UI');let f=document.querySelector('#packed-otp'),r=document.querySelector('#packed-otp-resend'),input=f.elements.namedItem('code');await act(async()=>user.click(f.querySelector('[type=submit]')));assert.equal(f.checkValidity(),false);await act(async()=>user.type(input,'001234'));assert(!f.querySelector('fieldset').disabled);assert.equal(input.value,'001234');await act(async()=>user.click(r.querySelector('button')));assert.equal(input.value,'');assert(f.querySelector('fieldset').disabled);assert(r.querySelector('fieldset').disabled);await press('Finish local preview');assert(document.activeElement===f.elements.namedItem('code'));await act(async()=>{await user.type(input,'001234');await user.click(f.querySelector('[type=submit]'));});assert(f.querySelector('fieldset').disabled);await press('Show host error');assert.equal(input.getAttribute('aria-invalid'),'true');assert(f.querySelector('[role=alert]'));await press('Show expired UI');assert.equal(f.querySelector('input'),null);assert(document.activeElement===document.querySelector('#packed-otp-status'));assert(!r.querySelector('fieldset').disabled);await press('Show locked UI');assert(r.querySelector('fieldset').disabled);await press('Show ready UI');assert.equal(f.elements.namedItem('code').value,'');await press('Toggle resend eligibility');assert(r.querySelector('fieldset').disabled);await act(async()=>{await user.type(f.elements.namedItem('code'),'001234');await user.click(f.querySelector('[type=submit]'));});await press('Finish local preview');assert.equal(f.querySelector('input'),null);assert(document.activeElement===document.querySelector('#packed-otp-status'));assert.deepEqual(warnings,[]);}finally{if(root)await act(async()=>root.unmount());console.error=old;dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}});
test('bare OTP forwards both form refs and clears them on unmount',async()=>{const dom=new JSDOM('<div id="root"></div>'),saved=new Map();for(const key of ['window','document','HTMLElement','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}let root;try{const {createRoot}=await import('react-dom/client'),verify=createRef(),resend=createRef();root=createRoot(document.querySelector('#root'));await act(async()=>root.render(h(OTPVerificationBlock,{id:'bare',action:'/verify',challengeState:'ready',resendAction:'/resend',ref:verify,resendFormRef:resend})));assert.equal(verify.current.id,'bare');assert.equal(resend.current.id,'bare-resend');await act(async()=>root.unmount());root=null;assert.equal(verify.current,null);assert.equal(resend.current,null);}finally{if(root)await act(async()=>root.unmount());dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}});
